// src/components/JobItem.jsx
import React, { useState } from "react";
import axios from "axios";
import "./JobItem.css";

const JobItem = ({ job, onJobDeleted, onJobUpdated }) => {
  const [isEditing, setEditing] = useState(false);
  const [newStatus, setNewStatus] = useState(job.status);

  const handleUpdate = async () => {
    try {
      await axios.put(`http://localhost:5000/api/jobs/${job._id}`, {
        ...job,
        status: newStatus,
      });
      setEditing(false);
      onJobUpdated();
    } catch (err) {
      console.error("Update failed:", err);
    }
  };

  const handleDelete = async () => {
    try {
      await axios.delete(`http://localhost:5000/api/jobs/${job._id}`);
      onJobDeleted(); // Refresh the job list
    } catch (err) {
      console.error("Delete failed:", err);
    }
  };

  return (
    <div className="job-details">
      <h3>{job.company}</h3>
      <p><strong>Position:</strong> {job.role || "Not specified"}</p>
      <p><strong>Date:</strong> {job.date}</p>
      <p><strong>Status:</strong> {isEditing ? (
        <select value={newStatus} onChange={(e) => setNewStatus(e.target.value)}>
          <option>Applied</option>
          <option>Interview</option>
          <option>Offer</option>
          <option>Rejected</option>
        </select>
      ) : (
        job.status
      )}</p>
      {job.link && (
        <p>
          <a href={job.link} target="_blank" rel="noopener noreferrer">
            View Job Application
          </a>
        </p>
      )}
      <div className="button-group">
        {isEditing ? (
          <button onClick={handleUpdate}>Save</button>
        ) : (
          <button onClick={() => setEditing(true)}>Update</button>
        )}
        <button onClick={handleDelete} className="delete-btn">Delete</button>
      </div>
    </div>
  );
};

export default JobItem;
